"""Fair value for a Polymarket up/down round, which settles on a TWAP.

WHY THIS IS NOT `digital.fair_value`
------------------------------------
The Binance wrapper settles on a POINT: `endPrice > startPrice`, measured
against the instantaneous price at the bell. Polymarket's `btc-5m-twap-60`
settles on the AVERAGE of the round, from its own market description:

    "resolve to Up if the TWAP of Bitcoin, generated by Chainlink, of the time
     range specified in the title is greater than or equal to the price at the
     BEGINNING of that range"

Same slug family, same 5-minute windows, different random variable. Measured on
48 settled rounds the two venues DISAGREED on 5 (10.4%). So a model calibrated
on the point rule is not a close approximation of this one -- it prices a
different bet.

THE DERIVATION
--------------
Work in log space. Let `x_t = ln(S_t / S_0)` be the driftless log-return since
the round opened, so `x_t ~ N(0, sigma^2 t)`. The round's average price is

    A = (1/T) * integral_0^T S_u du = S_0 * (1/T) * integral_0^T exp(x_u) du

and Up wins iff `A >= S_0`. The exponent is a few basis points inside a round,
so `exp(x) = 1 + x` to O(x^2) -- with x ~ 1e-4 the neglected term is ~1e-8, far
below the venue's 0.01 tick. The condition becomes

    Up  <=>  M := (1/T) * integral_0^T x_u du >= 0

i.e. the AVERAGE log-return over the round must be non-negative. That is the
whole difference from the point rule, which only asks about `x_T`.

Split at the current time t (tau = T - t remaining):

    M = [ J_t + integral_t^T x_u du ] / T ,     J_t := integral_0^t x_u du

`J_t` is KNOWN -- it is the realised part of the round. Given `x_t`, the
remaining integral is Gaussian with

    integral_t^T x_u du ~ N( x_t * tau , sigma^2 * tau^3 / 3 )

because `Var[integral_0^tau W_u du] = tau^3/3` for a standard Brownian motion.
So

    M ~ N( (J_t + x_t * tau) / T , sigma^2 * tau^3 / (3 T^2) )

and therefore

    P(Up) = Phi( (J_t + x_t * tau) / (sigma * tau^1.5 / (sqrt(3) * T)) )

In minutes, with `s` per-minute volatility and `X = sigma_1m`: the denominator is
`X * tau_m^1.5 / (sqrt(3) * T_m)`.

TWO CONSEQUENCES, BOTH CHECKABLE
--------------------------------
1. Ignore the realised part (`J_t = 0`, the start of the round) and the z-score
   is exactly `sqrt(3)` times the point rule's:

       z_twap = sqrt(3) * x_t / (X * sqrt(tau_m))  =  sqrt(3) * z_point

   `sqrt(3) = 1.732`: the TWAP rule is 1.73x LESS dispersed than the point rule.
   This reproduces, from the algebra, the factor that was measured independently
   from the 48-round comparison -- which is the main reason to trust the form.
2. The realised average `J_t` is an ANCHOR the point rule has no concept of. A
   round whose spot sits above the strike but whose average so far is below it
   is a DOWN bet, and vice versa. Both directions occur in the live tape; see
   `tests/test_twap_pricing.py::test_the_two_rules_disagree_in_both_directions`,
   and `twap_settles_up` below for the ground truth to score against.

`J_t` is a real input, not a detail: pass `realized_log_avg` (the average of
`ln(S_u/S_0)` over `[0, t]`). Leaving it out assumes the spot has been at its
current level all round, which flatters the model near the bell; `None` is
therefore treated as "assume flat", and the caller can do better.
"""
from __future__ import annotations

import math

from btcpredict.pricing.digital import norm_cdf

#: The venue's own resolution config: `cryptoMarketConfig {id: btc-5m-twap-60,
#: twapLookbackSeconds: 60}`. A 5-minute round is 300 seconds.
TWAP_LOOKBACK_S = 60
ROUND_SECONDS_5M = 300
ROUND_SECONDS_15M = 900

#: Clamp, so no single input yields 0.0/1.0 and implies infinite edge.
_EPS = 1e-6


def round_seconds(tau_s: float, elapsed_s: float | None = None) -> float:
    """Length of the round. Preferred from elapsed + remaining; else inferred.

    Called with only `tau_s` this cannot know the round's length, so it falls
    back to 300s -- the only round length the TRAIN-style "first four minutes"
    logic is defined for. A 900s caller must pass `elapsed_s`.
    """
    if elapsed_s is not None and elapsed_s >= 0 and tau_s > 0:
        return elapsed_s + tau_s
    return float(ROUND_SECONDS_5M)


def twap_fair_value(
    S_now: float,
    K: float,
    tau_s: float,
    sigma_1m: float,
    *,
    elapsed_s: float | None = None,
    realized_log_avg: float | None = None,
) -> float:
    """P(the round settles Up) under a TWAP settlement.

    S_now             current spot
    K                 the round's START price (strike)
    tau_s             seconds remaining until the bell
    sigma_1m          per-minute log-return standard deviation
    elapsed_s         seconds since the round opened, if known
    realized_log_avg  mean of ln(S_u / K) over [0, elapsed], if known

    Returns 0.5 at the open (nothing is known yet) and degenerates correctly to
    a point decision as tau -> 0.
    """
    if S_now <= 0 or K <= 0:
        raise ValueError(f"prices must be positive (S={S_now}, K={K})")
    if sigma_1m <= 0:
        raise ValueError(f"sigma must be positive (got {sigma_1m})")
    if tau_s <= 0:
        # Nothing left to average: the answer is the sign of the realised
        # integral. Without history, fall back to the level.
        if realized_log_avg is not None:
            return 1.0 - _EPS if realized_log_avg > 0 else _EPS
        return 1.0 - _EPS if S_now > K else _EPS

    T_s = round_seconds(tau_s, elapsed_s)
    x = math.log(S_now / K)

    # J_t: the known part of the round's integral. "Assume flat" when unknown.
    if realized_log_avg is not None and elapsed_s is not None and elapsed_s > 0:
        J_t = realized_log_avg * elapsed_s
    elif realized_log_avg is not None:
        J_t = realized_log_avg * (T_s - tau_s)
    else:
        J_t = x * (T_s - tau_s)

    tau_m = tau_s / 60.0
    T_m = T_s / 60.0
    sd_M = sigma_1m * (tau_m ** 1.5) / (math.sqrt(3.0) * T_m)
    if sd_M <= 0:
        # tau_m > 0 and sigma_1m > 0, so this needs T_m to be infinite.
        return 1.0 - _EPS if (J_t + x * tau_s) > 0 else _EPS
    z = (J_t + x * tau_s) / (T_s * sd_M)
    return min(1.0 - _EPS, max(_EPS, norm_cdf(z)))


def twap_z(
    S_now: float,
    K: float,
    tau_s: float,
    sigma_1m: float,
    *,
    elapsed_s: float | None = None,
    realized_log_avg: float | None = None,
) -> float:
    """The z-score the TWAP fair value is built on (same arguments).

    Positive means Up is favoured. This is the quantity to gate on, and it is
    NOT `sqrt(3) * digital.moneyness_sd` except in the `J_t = 0` limit.
    """
    if S_now <= 0 or K <= 0 or sigma_1m <= 0 or tau_s <= 0:
        return math.inf if S_now > K else -math.inf
    T_s = round_seconds(tau_s, elapsed_s)
    x = math.log(S_now / K)
    if realized_log_avg is not None and elapsed_s is not None and elapsed_s > 0:
        J_t = realized_log_avg * elapsed_s
    elif realized_log_avg is not None:
        J_t = realized_log_avg * (T_s - tau_s)
    else:
        J_t = x * (T_s - tau_s)
    tau_m = tau_s / 60.0
    T_m = T_s / 60.0
    sd_M = (tau_m ** 1.5) / (math.sqrt(3.0) * T_m) * sigma_1m
    return (J_t + x * tau_s) / (T_s * sd_M)


def twap_dispersion_ratio() -> float:
    """How much less dispersed the TWAP rule is than the point rule.

    Exactly `sqrt(3)` by the algebra above; exposed as a function so the
    constant is asserted in a test rather than scattered as a literal.
    """
    return math.sqrt(3.0)


def point_rule_z(S_now: float, K: float, tau_s: float, sigma_1m: float) -> float:
    """The z-score the Binance wrapper's point rule implies, for comparison."""
    if S_now <= 0 or K <= 0 or sigma_1m <= 0 or tau_s <= 0:
        return math.inf if S_now > K else -math.inf
    return math.log(S_now / K) / (sigma_1m * math.sqrt(tau_s / 60.0))


def twap_settles_up(
    samples: list[tuple[float, float]], start_price: float,
    *, start_ms: float | None = None, end_ms: float | None = None,
) -> bool | None:
    """Ground truth: did the round settle Up under the TWAP rule?

    `samples` is [(t_ms, price), ...]. Returns None when there is nothing to
    average. This is the label to score a TWAP model against, and the reason
    the model cannot be validated on the wrapper's own settlement column: on
    10.4% of rounds the two labels differ.

    Time-weighted, not sample-weighted: a mean over irregular ticks is a
    different quantity, and the venue averages over TIME.
    """
    if not samples or start_price <= 0:
        return None
    pts = sorted((t, p) for t, p in samples if p and p > 0)
    if start_ms is not None:
        pts = [(t, p) for t, p in pts if t >= start_ms]
    if end_ms is not None:
        pts = [(t, p) for t, p in pts if t <= end_ms]
    if len(pts) < 2:
        return None
    num = 0.0
    den = 0.0
    for (t0, p0), (t1, p1) in zip(pts, pts[1:]):
        dt = t1 - t0
        if dt <= 0:
            continue
        num += 0.5 * (p0 + p1) * dt      # trapezoid: the price held over dt
        den += dt
    if den <= 0:
        return None
    return (num / den) >= start_price
